import{_ as a,o,c as t,a2 as s}from"./chunks/framework.CfwCq2QB.js";const i="/dev-go-docs/shots/0.2.3/en/light/popup-tools.png",h=JSON.parse('{"title":"Media sniffer & bulk download","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/media-sniffer.md","filePath":"en/features/media-sniffer.md"}'),n={name:"en/features/media-sniffer.md"};function r(d,e,l,u,p,c){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="media-sniffer-bulk-download" tabindex="-1">Media sniffer &amp; bulk download <a class="header-anchor" href="#media-sniffer-bulk-download" aria-label="Permalink to &quot;Media sniffer &amp; bulk download&quot;">​</a></h1><p>In one line: sniff the images, videos, and audio on the current tab; filter, search, and download them one by one or in bulk.</p><h2 id="how-to-use" tabindex="-1">How to use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to use&quot;">​</a></h2><p>Open the target page and press <code>Alt+4</code> (or open the popup&#39;s Resources page):</p><ul><li>Images, videos, and audio loaded by the tab are listed automatically; &quot;Refresh&quot; rescans, &quot;Clear&quot; empties the list</li><li><strong>Filter</strong>: All / Images / Videos; <strong>search</strong> covers name, domain, and type</li><li>Each entry shows its source (request capture / page DOM) and type; images and common video formats preview inline</li><li>Download / copy link / open link per entry, or &quot;Download all&quot; to create every download at once</li></ul><img src="'+i+'" alt="The popup&#39;s Resources page" style="width:60%;display:block;margin-left:auto;margin-right:auto;"><p><em>The popup&#39;s Resources page: type filters, search, and &quot;Download all&quot;.</em></p><h2 id="about-streaming-media" tabindex="-1">About streaming media <a class="header-anchor" href="#about-streaming-media" aria-label="Permalink to &quot;About streaming media&quot;">​</a></h2><p>Video sites mostly use HLS / DASH streaming (m3u8 / mpd manifests plus segments). DevGo recognizes and lists these, but <strong>doesn&#39;t stitch downloads</strong>:</p><ul><li>Stream manifests and segments saved directly won&#39;t produce a complete video; DevGo says so and skips them, so you don&#39;t download useless files</li><li>X (Twitter) videos come as separate audio / video tracks, likewise flagged as needing a merge</li><li>For a complete video, copy the link and hand it to a downloader like yt-dlp</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Only <code>http</code> / <code>https</code> resources can be downloaded</li><li>Sniffing covers the <strong>current tab</strong>: switching tabs repopulates the list — download what you need first</li></ul>',12)])])}const f=a(n,[["render",r]]);export{h as __pageData,f as default};
